-- ==============================================================================
-- MCA Memories 2025–2027 Seed: 72 Authentic Memory Questions
-- File: supabase/seed_questions.sql
-- Description: Inserts the actual 72 yearbook memory questions (preserved from 01_questions.sql)
-- Safe to re-run: Uses ON CONFLICT (question_number) DO UPDATE
-- ==============================================================================

ON CONFLICT (question_number) DO UPDATE 
SET 
  question_text = EXCLUDED.question_text,
  description = COALESCE(EXCLUDED.description, questions.description, ''),
  is_active = EXCLUDED.is_active,
  updated_at = timezone('utc'::text, now());
